SpriteDepthNode* previous = 0;
SpriteDepthNode* cursor = head;
if (cursor != 0) {
    while (cursor != 0 && depth_key < cursor->depth_key) {
        previous = cursor;
        cursor = cursor->next;
    }
    if (cursor == 0) {
        previous->next = node;
        node->next = 0;
    } else if (previous == 0) {
        node->next = cursor;
        g_sprite_depth_buckets[bucket_index] = node;
    } else {
        previous->next = node;
        node->next = cursor;
    }
} else {
    g_sprite_depth_buckets[bucket_index] = node;
    node->next = 0;
}

